frappe.ui.form.on('Project', {
	refresh(frm) {
		// your code here
		//frappe.breadcrumbs.clear();
        //frappe.breadcrumbs.append_breadcrumb_element('../../../app/мои-проекты', 'Мои проекты');
        //frappe.breadcrumbs.append_breadcrumb_element('../../../app/project', 'Проекты');
        //frappe.breadcrumbs.append_breadcrumb_element( '', frm.doc.name);

		frm.dashboard.heatmap_area.hide();
		//frm.dashboard.heatmap.update - обновить данные хитмап
		frm.dashboard.transactions_area.empty();
		frm.dashboard.data_rendered = false;
		frm.dashboard.data.transactions = [
            {
                "label": __("Задачи"),
                "items": [
                    "Task",
                    "Issue",
                    "Meeting Notes",
                ]
            },{
                "label": "Expenses",
                "items": [
                    "Purchase Invoice",
                    "Journal Entry",
                    //"Expense Claim"
                ]
            },{
                "label": "Sales",
                "items": [
                    "Sales Invoice"
                ]
            }
        ];
        frm.dashboard.render_links();
        //frm.dashboard.set_open_count();

        frm.page.add_inner_button(__("Отчетность P&L"), 
		    () => {
		        frappe.route_options = {
					project: frm.docname,
		            periodicity: "Monthly",
		            filter_based_on: "Date Range",
		            period_start_date: frm.doc.expected_start_date,
		            period_end_date: frm.doc.expected_end_date,
				};
		        frappe.set_route('query-report', 'Profit and Loss Statement');
		    }
		    ,__("Actions"));

		frm.page.add_inner_button(__("Дерево задач проекта"), 
		    () => {
		        frappe.route_options = {
					project: frm.docname,
				};
		        frappe.set_route('Tree', 'Task', {"project": frm.docname} );
		    }
		    ,__("View"));
		/*frm.page.add_inner_button(__("Список задач проекта"), 
		    () => {
		        frappe.route_options = {
					project: frm.docname,
				};
		        frappe.set_route('List', 'Task');
		    }
		    ,__("View"));/**/
	}
})
